// Arimo (Regular + Bold) - vendored Latin font for jsPDF, embedded in every PDF
// in place of the built-in Helvetica (which isn't embedded and only covers
// Windows-1252, so names like "Łukasz" or "Şahin" printed as garbage).
// Arimo has the same character widths as Helvetica, so cards lay out the same.
// Subset of Arimo-Regular.ttf / Arimo-Bold.ttf 1.33 (SIL OFL 1.1, see
// arimo-OFL.txt) to Latin-1, Latin Extended-A, Romanian and Vietnamese,
// unhinted; see lib/README.md for how to rebuild it.
// Source: https://github.com/googlefonts/Arimo/tree/22e482e2ce0ebb2e6f88ba49d029d60f558d5d67/fonts/ttf
(function (jsPDFAPI) {
  "use strict";
  var regular = "";
  var bold = "";
  jsPDFAPI.events.push(["addFonts", function () {
    this.addFileToVFS("Arimo-Regular.ttf", regular);
    this.addFont("Arimo-Regular.ttf", "Arimo", "normal");
    this.addFileToVFS("Arimo-Bold.ttf", bold);
    this.addFont("Arimo-Bold.ttf", "Arimo", "bold");
  }]);
})(window.jspdf.jsPDF.API);
